package com.securevault.service;
import com.securevault.entity.*; import com.securevault.repository.PasswordHistoryRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class PasswordHistoryService{private final PasswordHistoryRepository repo;private final PasswordEncoder pe;public PasswordHistoryService(PasswordHistoryRepository r,PasswordEncoder p){repo=r;pe=p;}public void record(User u,String hash){PasswordHistory h=new PasswordHistory();h.setUser(u);h.setPasswordHash(hash);repo.save(h);}public boolean wasRecentlyUsed(User u,String raw){for(PasswordHistory h:repo.findTop5ByUserOrderByChangedAtDesc(u))if(pe.matches(raw,h.getPasswordHash()))return true;return false;}}
